<script setup>
import { onMounted,ref } from 'vue'
import { api } from './api'
const fields=ref([]),loading=ref(false),error=ref(''),editing=ref(null),creating=ref(false)
const blank=()=>({label:'',key:'',field_type:'text',required:false,active:true,sort_order:100,options:[]})
const form=ref(blank())
async function load(){loading.value=true;error.value='';try{fields.value=await api.platformContactFields()}catch(e){error.value=e.message}finally{loading.value=false}}
function create(){creating.value=true;editing.value=null;form.value=blank()}
function edit(f){creating.value=false;editing.value=f;form.value={...f,options:[...(f.options||[])]}}
function close(){creating.value=false;editing.value=null}
async function save(){try{const payload={...form.value,options:form.value.field_type==='select'?form.value.options:[]};if(creating.value)await api.createContactField(payload);else await api.updateContactField(editing.value.id,payload);close();await load()}catch(e){error.value=e.message}}
async function remove(f){if(f.system||!confirm(`Delete custom field “${f.label}”? Existing values will also be removed.`))return;try{await api.deleteContactField(f.id);await load()}catch(e){error.value=e.message}}
function addOption(){form.value.options.push('')}
function removeOption(i){form.value.options.splice(i,1)}
onMounted(load)
</script>
<template><section class="cf-page"><header><div><p class="eyebrow">CONTACT DATA</p><h1>Custom Fields</h1><p>Manage fields shared by WhatsApp, Telegram and manually created subscribers.</p></div><button class="primary" @click="create">+ Create Field</button></header><div class="notice"><b>Shared field catalogue</b><span>System fields are maintained automatically from incoming channel data. Custom fields are available to flows, variables, conditions and HTTP APIs across both channels.</span></div><p v-if="error" class="error">{{error}}</p><div class="card"><div class="card-title"><div><h2>System Fields</h2><p>Protected fields populated automatically by WA Connect.</p></div></div><div class="field-grid head"><span>Field</span><span>Variable</span><span>Type</span><span>Behaviour</span><span></span></div><div v-for="f in fields.filter(x=>x.system)" :key="f.key" class="field-grid"><div><b>{{f.label}}</b><small>{{f.key}}</small></div><code>{{f.variable}}</code><span class="pill">{{f.field_type}}</span><span class="muted">Automatic</span><button class="icon" @click="edit(f)">✎</button></div></div><div class="card"><div class="card-title"><div><h2>Custom Fields</h2><p>Create reusable subscriber data fields for automations and integrations.</p></div><button class="secondary" @click="load">↻ Refresh</button></div><div class="field-grid head"><span>Field</span><span>Variable</span><span>Type</span><span>Status</span><span></span></div><div v-if="!fields.filter(x=>!x.system).length" class="empty">{{loading?'Loading…':'No custom fields yet.'}}</div><div v-for="f in fields.filter(x=>!x.system)" :key="f.key" class="field-grid"><div><b>{{f.label}}</b><small>{{f.key}}</small></div><code>{{f.variable}}</code><span class="pill">{{f.field_type}}</span><span :class="['status',f.active?'on':'off']">{{f.active?'Active':'Inactive'}}</span><div class="actions"><button class="icon" @click="edit(f)">✎</button><button class="icon danger" @click="remove(f)">×</button></div></div></div><div v-if="creating||editing" class="modal-bg" @click.self="close"><form class="modal" @submit.prevent="save"><div class="modal-head"><div><p class="eyebrow">{{creating?'NEW FIELD':'EDIT FIELD'}}</p><h2>{{creating?'Create Custom Field':form.label}}</h2></div><button type="button" class="x" @click="close">×</button></div><label>Field name<input v-model="form.label" required maxlength="120"></label><label>Variable / key<input v-model="form.key" :disabled="!!editing" required pattern="[a-z][a-z0-9_]*" placeholder="customer_number"><small v-if="creating">Used as %{{form.key||'field_key'}}%</small></label><label>Field type<select v-model="form.field_type" :disabled="editing?.system"><option value="text">Text</option><option value="textarea">Textarea</option><option value="email">Email</option><option value="number">Number</option><option value="date">Date</option><option value="select">Select</option><option value="checkbox">Checkbox</option></select></label><div v-if="form.field_type==='select'" class="options"><b>Options</b><div v-for="(_,i) in form.options" :key="i"><input v-model="form.options[i]" required><button type="button" @click="removeOption(i)">×</button></div><button type="button" class="secondary" @click="addOption">+ Add option</button></div><label>Sort order<input v-model.number="form.sort_order" type="number"></label><div v-if="!editing?.system" class="checks"><label><input v-model="form.required" type="checkbox"> Required</label><label><input v-model="form.active" type="checkbox"> Active</label></div><p v-else class="system-note">System fields are protected. You can change the display name and sort order, but not their key, type or active state.</p><footer><button type="button" class="secondary" @click="close">Cancel</button><button class="primary" type="submit">Save Field</button></footer></form></div></section></template>
<style scoped>
.cf-page{margin-left:220px;min-height:100vh;padding:34px 38px;background:#f4f7f6;color:#13251d}.cf-page header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:22px}.eyebrow{margin:0 0 5px;color:#119052;font-size:11px;font-weight:800;letter-spacing:.08em}.cf-page h1{font-size:30px;margin:0 0 5px}.cf-page header p:last-child,.card-title p{margin:0;color:#74867e}.primary,.secondary,.icon,.x{cursor:pointer}.primary{border:0;background:#119c59;color:#fff;border-radius:8px;padding:11px 16px;font-weight:700}.secondary{border:1px solid #cedbd5;background:#fff;border-radius:8px;padding:8px 12px}.notice{display:flex;gap:12px;background:#edf8f3;border:1px solid #c9e8da;border-radius:11px;padding:14px 16px;margin-bottom:20px}.notice span{color:#61776d}.card{background:#fff;border:1px solid #dce6e1;border-radius:14px;margin-bottom:20px;overflow:hidden}.card-title{display:flex;justify-content:space-between;align-items:center;padding:18px 20px;border-bottom:1px solid #e6ece9}.card-title h2{margin:0 0 4px;font-size:18px}.field-grid{display:grid;grid-template-columns:2fr 1.6fr 1fr 1fr 90px;align-items:center;gap:14px;padding:14px 20px;border-bottom:1px solid #edf1ef}.field-grid:last-child{border-bottom:0}.field-grid.head{background:#f8faf9;color:#72847b;font-size:11px;font-weight:700;text-transform:uppercase}.field-grid b,.field-grid small{display:block}.field-grid small,.muted{color:#7c8d85}.field-grid code{background:#f2f6f4;border-radius:6px;padding:5px 7px;width:max-content}.pill,.status{font-size:11px;border-radius:999px;padding:5px 8px;width:max-content}.pill{background:#edf3ff;color:#315d9b}.status.on{background:#e4f7ec;color:#08753c}.status.off{background:#f1f2f2;color:#68736e}.actions{display:flex;justify-content:flex-end;gap:6px}.icon{border:1px solid #d7e1dc;background:#fff;border-radius:7px;width:34px;height:34px}.danger{color:#b92c2c}.empty{padding:30px;text-align:center;color:#788a82}.error{background:#fff0f0;color:#a52b2b;padding:11px;border-radius:8px}.modal-bg{position:fixed;inset:0;background:#0b241b88;z-index:300;display:grid;place-items:center}.modal{width:min(520px,92vw);max-height:88vh;overflow:auto;background:#fff;border-radius:14px;padding:22px}.modal-head{display:flex;justify-content:space-between}.modal-head h2{margin:0 0 18px}.x{border:0;background:none;font-size:24px}.modal>label{display:block;font-weight:600;margin:13px 0}.modal input:not([type=checkbox]),.modal select{box-sizing:border-box;width:100%;margin-top:6px;padding:10px;border:1px solid #cedbd5;border-radius:7px}.modal label small{display:block;color:#75867f;margin-top:4px}.checks{display:flex;gap:25px;margin:15px 0}.checks label{display:flex;gap:7px}.options{background:#f7f9f8;padding:12px;border-radius:9px}.options>div{display:flex;gap:7px;margin:7px 0}.options>div input{margin:0!important}.options>div button{border:0;background:#fee;color:#a22;border-radius:6px}.system-note{background:#f3f7f5;color:#63776e;padding:10px;border-radius:7px}.modal footer{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}
</style>